```html
<html>
  <head>
    <title>Pendulum Simulation</title>
  </head>
  <body>
    <canvas id="pendulum-canvas" width="400" height="400"></canvas>
    <input type="number" id="initial-angle" value="45" />
    <button id="start-button">Start</button>
    <script>
      const canvas = document.getElementById('pendulum-canvas');
      const ctx = canvas.getContext('2d');
      canvas.width = 400;
      canvas.height = 400;

      let angle = 0;
      let velocity = 0;
      let gravity = 0.0981; // m/s^2 (approximately 1g)
      let ba = 50; // length of the pendulum (approx 0.5m)
      let da = 2; // damping coefficient (air resistance)

      document.getElementById('start-button').addEventListener('click', () => {
        angle = parseInt(document.getElementById('initial-angle').value);
        velocity = 0;
        simulate();
      });

      function simulate() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'black';
        ctx.fillRect(200, 200, canvas.width, canvas.height);

        // calculate new velocity
        velocity += gravity * Math.sin(angle) / ba - da * velocity * 0.01;

        // update angle
        angle += velocity * 0.1;

        // ensure pendulum doesn't swing too far
        if (angle > Math.PI/2) {
          angle = Math.PI/2;
          velocity = -velocity * 0.5; // decrease velocity to try to stop pendulum
        } else if (angle < -Math.PI/2) {
          angle = -Math.PI/2;
          velocity = -velocity * 0.5; // decrease velocity to try to stop pendulum
        }

        // draw pendulum
        ctx.beginPath();
        ctx.arc(200, 200, 20, Math.PI/2 - angle, Math.PI/2 + angle, false);
        ctx.fillStyle = 'blue';
        ctx.fill();

        // draw pivot
        ctx.beginPath();
        ctx.arc(200, 200, 10, 0, 2 * Math.PI, false);
        ctx.fillStyle = 'red';
        ctx.fill();

        // ask for next frame
        requestAnimationFrame(simulate);
      }
    </script>
  </body>
</html>
```

